import {pixelIcon,glassIcon} from './pixel-icons.js';
import {config} from './config.js';
import {KEY,initialState,hydrateState,createTransaction,settleTransaction,claimBonus,toggleFavorite} from './state.js';
let D;
try{const response=await fetch('/data.json');if(!response.ok)throw new Error();D=await response.json();}catch{document.querySelector('#app').textContent='Katalog belum berhasil dimuat. Silakan muat ulang halaman.';throw new Error('Catalog unavailable');}
const app=document.querySelector('#app'), overlays=document.querySelector('#overlay-root');
let S;try{S=hydrateState(JSON.parse(localStorage.getItem(KEY)));}catch{S=initialState();}
let toastTimer,heroIndex=0,heroRequest=0,specialIndex=0,pageLimit=30,returnFocus,chatMessages=[{self:false,text:'Halo! Selamat datang di pratinjau Playground. Saya dapat membantu Anda menjelajahi menu, promosi dan simulasi transaksi.'}];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'Rp '+Number(n).toLocaleString('id-ID');
const date=v=>new Intl.DateTimeFormat(S.locale==='en'?'en-GB':'id-ID',{dateStyle:'medium',timeStyle:'short'}).format(new Date(v));
const id=()=>crypto.randomUUID();
const dictionary={'Beranda':'Home','Eksklusif':'Exclusive','Promosi':'Promotions','Kontak':'Contact','Masuk':'Login','Daftar':'Register','Cari':'Search','Lihat semua':'View all','Informasi akun':'Account information','Riwayat Bermain':'Play history','Aktivitas':'Activity','Akun Saya':'My account','Keluar':'Logout','Semua':'All','Favorit':'Favorites','Permainan':'Games','Histori':'History','Tutup':'Close','Kembali':'Back','Saldo demo':'Demo balance','Belum ada data':'No data yet','Simpan':'Save','Batal':'Cancel','Kirim':'Send','Tidak ada permainan':'No games found','Cari permainan':'Search games','Hasil pencarian':'Search results'};
const t=s=>S.locale==='en'?(dictionary[s]||s):s;
const paths={menu:'M4 6h16M4 12h16M4 18h16',user:'M20 21a8 8 0 0 0-16 0M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',mail:'M3 5h18v14H3zM3 5l9 7 9-7',wallet:'M3 6h16v14H3zM3 6V4h13M15 11h7v5h-7zM18 13.5h.1',gift:'M3 8h18v4H3zM5 12v9h14v-9M12 8v13M12 8H8a3 3 0 1 1 3-3zM12 8h4a3 3 0 1 0-3-3z',history:'M3 11a9 9 0 1 1 2 7M3 5v6h6M12 7v5l3 2',search:'M21 21l-6-6M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',arrow:'M9 5l7 7-7 7',left:'M15 5l-7 7 7 7',close:'M6 6l12 12M18 6L6 18',star:'M12 3l2.8 5.7 6.2.9-4.5 4.4 1.1 6.2L12 17.3l-5.6 2.9 1.1-6.2L3 9.6l6.2-.9z',play:'M8 4l12 8-12 8z',home:'M3 10l9-7 9 7M5 9v12h5v-7h4v7h5V9',volume:'M3 9h4l5-5v16l-5-5H3zM16 8a6 6 0 0 1 0 8M19 5a10 10 0 0 1 0 14',refresh:'M20 7A9 9 0 1 0 21 15M20 3v5h-5',copy:'M8 8h13v13H8zM16 8V3H3v13h5',chat:'M3 3h18v14H8l-5 4zM7 8h10M7 12h6',check:'M4 12l5 5L20 6',bank:'M2 8l10-6 10 6zM4 21h16M5 10v8M12 10v8M19 10v8',filter:'M3 5h18M6 12h12M9 19h6',trophy:'M8 3h8v7a4 4 0 0 1-8 0zM8 5H3v3a5 5 0 0 0 5 5M16 5h5v3a5 5 0 0 1-5 5M12 14v5M8 21h8',logout:'M9 4H3v16h6M10 12h12M17 7l5 5-5 5',download:'M12 3v12M7 10l5 5 5-5M3 17v4h18v-4'};
const icon=(name,cls='')=>pixelIcon(name,cls)||`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.play}"/></svg>`;
const link=(url,html,cls='',attrs='')=>`<a data-route href="${esc(url)}" class="${cls}" ${attrs}>${html}</a>`;
const image=(src,alt,cls='',priority=false)=>`<img src="${esc(src||D.illustrations.fishing)}" alt="${esc(alt)}" class="${cls}" ${priority?'fetchpriority="high"':'loading="lazy"'} decoding="async">`;
const path=()=>location.pathname.replace(/\/+$/,'')||'/';
const current=()=>new URL(location.href);
function save(){try{localStorage.setItem(KEY,JSON.stringify(S));}catch{toast('Penyimpanan browser tidak tersedia; data hanya bertahan pada sesi ini.');}}
function log(text){S.activity.unshift({id:id(),text,time:new Date().toISOString()});S.activity=S.activity.slice(0,100);save();}
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3500);}
function go(url){const u=new URL(url,location.origin);if(u.origin!==location.origin)return;if(u.pathname==='/en'){S.locale='en';save();u.pathname='/';}closeModal();history.pushState({},'',u.pathname+u.search);pageLimit=30;render();window.scrollTo(0,0);}
function rerender(){const y=scrollY;render();window.scrollTo(0,y);}
function navIcon(name,muted=false){return D.navIcons[name+(muted?'-muted':'')]||D.navIcons[name]||D.navIcons.slots;}
const primaryCategories=new Set(['slots','casino','poker','lotto','arcade','fishing','promo','leaderboard','referral','chat']);
function categoryIcon(name,label){return glassIcon(name,'category-icon')||image(navIcon(name),label);}
function navMarkup(primary=false){return config.navigation.filter(([name])=>!primary||primaryCategories.has(name)).map(([name,label,url])=>link(url,`<span class="category-icon-wrap">${categoryIcon(name,label)}</span><span>${t(label)}</span>`,'nav-item '+(path().startsWith('/'+url.split('/')[1])?'active':''))).join('');}
function categoryNavigation(){
 const featured=[['arcade','Semua','/search'],['slots','Slots','/slot/category/hot'],['spade','Live Casino','/casino/category/lobby'],['cards','Card','/poker'],['sports','Sports','/sports'],['fishing','Fishing','/fishing']];
 const extra=config.navigation.filter(([name])=>['lotto','arcade','promo','leaderboard','referral','chat'].includes(name));
 return `<nav class="main-nav" aria-label="Kategori utama">${[...featured,...extra].map(([name,label,url])=>link(url,`<span class="category-icon-wrap">${categoryIcon(name,label)}</span><span>${t(label)}</span>`,'nav-item '+(path()===url?'active':''))).join('')}</nav>`;
}
function announcement(){return `<div class="ticker">${icon('volume')}<div class="ticker-window"><span class="ticker-text">${esc(config.announcement)}</span></div></div>`;}
function accountLinks(){
 return [['user','Informasi akun','/user'],['wallet','Deposit','/deposit'],['bank','Withdraw','/withdraw/bank-transfer'],['gift','Bonus','/user/bonuses'],['user','Referral','/user/referral/history'],['mail','Inbox','/user/messages'],['history','Aktivitas','/user/activity'],['history','Riwayat Bermain','/user/history']].map(([i,label,url])=>link(url,icon(i)+esc(t(label)),' '+(path()===url?'active':''))).join('');
}
function brandLogo(){return link('/',`<span class="brand-wordmark" aria-hidden="true"><span class="brand-number">64</span><span class="brand-letters">COR</span></span>`,'logo','aria-label="64COR"');}
function header(){return `<header class="header"><div class="container header-inner">${brandLogo()}<div class="header-account">${link('/deposit',icon('deposit')+'<span>'+t('Deposit')+'</span>','btn header-deposit')}${link('/user/messages',icon('bell')+(S.signedIn&&S.messages.some(m=>!m.read)?'<span class="notification-dot"></span>':''),'icon-button inbox-button','aria-label="Notifikasi"')}${S.signedIn?link('/user',icon('user'),'icon-button header-profile','aria-label="Akun saya"'):`<button class="icon-button header-profile" data-action="auth" data-mode="login" aria-label="Masuk">${icon('user')}</button>`}</div></div></header>`;}
function footer(){return `<footer class="footer"><div class="container"><details class="footer-about"><summary>64COR — Jelajahi dunia permainan</summary><p>Temukan beragam kategori, provider dan program promosi dalam satu tampilan. Template Playground menyatukan navigasi katalog, halaman member dan simulasi wallet dalam pengalaman yang konsisten di berbagai ukuran layar.</p><p>Gunakan pratinjau untuk menguji pencarian, daftar favorit, navigasi serta alur transaksi demo sebelum integrasi sistem admin.</p></details><h3 style="margin-top:24px">Metode deposit</h3><div class="payment-logos">${D.payments.map(p=>image(p.image,p.title)).join('')}</div><h3>Partner</h3><div class="partners">${D.providers.map(p=>link(p.path,image(p.image,'')+'<span>'+esc(p.name)+'</span>')).join('')}</div><div class="footer-links"><details class="footer-group"><summary>${t('Permainan')}</summary><div class="footer-group-links"><button class="text-button" data-action="drawer" aria-label="Buka menu" aria-expanded="false">Semua menu ${icon('menu')}</button>${config.navigation.slice(0,8).map(([,l,u])=>link(u,t(l))).join('')}</div></details><details class="footer-group"><summary>Informasi</summary><div class="footer-group-links">${[['Tentang Kami','/about-us'],['Kontak','/contact'],['Promosi','/promotions/all'],['Leaderboard','/leaderboard/distributed']].map(([l,u])=>link(u,t(l))).join('')}</div></details><details class="footer-group"><summary>Member</summary><div class="footer-group-links">${[['Deposit','/deposit'],['Withdraw','/withdraw/bank-transfer'],['Referral','/referral'],['Bonus','/user/bonuses']].map(([l,u])=>link(u,t(l))).join('')}</div></details><details class="footer-group"><summary>Bantuan</summary><div class="footer-group-links">${[['Responsible Gaming','/legal/responsible-gaming'],['Syarat & Ketentuan','/legal/terms-and-conditions'],['Kebijakan Privasi','/legal/privacy-policy'],['Pengaduan Konsumen','/complaint']].map(([l,u])=>link(u,l)).join('')}<button class="text-button" data-action="chat">Live Chat</button></div></details></div><div class="copyright"><span>© 2026 64COR · Powered by Soft Tech</span><span><button class="text-button" data-action="locale" data-locale="id">Indonesia</button> · <button class="text-button" data-action="locale" data-locale="en">English</button></span></div><p class="demo-notice">${config.demoNotice} Tidak terhubung dengan layanan atau akun GOBI88.</p><button class="text-button small-text" data-action="reset-prompt">Reset data demo</button></div></footer><button class="float-help" data-action="chat" aria-label="Buka live chat demo">${pixelIcon('chat')}</button>`;}
function breadcrumbs(){return `<nav class="breadcrumbs" aria-label="Breadcrumb">${link('/',t('Beranda'),path()==='/'?'active':'')}${config.navigation.slice(0,9).map(([,label,url])=>link(url,t(label),path().startsWith('/'+url.split('/')[1])?'active':'')).join('')}</nav>`;}
function section(title,ico,body,href='',cls=''){return `<section class="section ${cls}"><div class="section-head"><h2 class="section-title">${categoryIcon(ico,title)}<span>${t(title)}</span></h2>${href?link(href,t('Lihat semua')+icon('arrow'),'all-link'):''}</div>${body}</section>`;}
function card(g,featured=false){return `<article class="game-card${g.family==='casino'?' game-card--portrait':''}">${featured?'<span class="hot-badge">HOT</span>':''}${link('/play/'+g.family+'/'+g.id,image(g.image,g.title)+`<span class="game-play">${icon('play')}</span>`,'game-image')}<button class="favorite ${S.favorites.includes(g.id)?'selected':''}" data-action="favorite" data-id="${g.id}" aria-label="${S.favorites.includes(g.id)?'Hapus favorit':'Tambah favorit'} ${esc(g.title)}" aria-pressed="${S.favorites.includes(g.id)}">${icon('star')}</button>${link('/play/'+g.family+'/'+g.id,esc(g.title),'game-name','title="'+esc(g.title)+'"')}</article>`;}
const grid=(games,cls='')=>`<div class="game-grid ${cls}">${games.map(g=>card(g)).join('')}</div>`;
function providerRail(family='slot'){const cats=family==='slot'?[['hot','Hot'],['exclusive','Exclusive'],['new','New']]:[['hot','Hot'],['new','New']];return `<section class="section provider-section"><h2 class="section-title">${image(navIcon(family==='slot'?'slots':'arcade',true),family)}<span>${family==='slot'?'Slots':'Arcade'}</span></h2><button class="rail-button" data-action="rail" data-direction="-1" aria-label="Provider sebelumnya">${icon('left')}</button><div class="rail">${cats.map(([k,l])=>link('/'+family+'/category/'+k,image(D.categoryIcons[k]||D.navIcons[family==='slot'?'hot-muted':'arcade-muted'],l)+'<span>'+l+'</span>','provider')).join('')}${D.providers.filter(p=>p.family===family).map(p=>link(p.path,image(p.image,p.name)+'<span>'+esc(p.name)+'</span>','provider')).join('')}</div><button class="rail-button" data-action="rail" data-direction="1" aria-label="Provider berikutnya">${icon('arrow')}</button>${link('/'+family+'/category/hot',t('Lihat semua')+icon('arrow'),'all-link')}</section>`;}
function hero(){return `<div class="hero-layout"><div class="hero-primary"><section class="carousel" aria-label="Promosi utama" aria-roledescription="carousel">${D.banners.map((b,i)=>link(b.path,`<img src="${esc(b.image)}" alt="${esc(b.title||'Banner promosi '+(i+1))}" width="2048" height="683" loading="eager" decoding="async" fetchpriority="${i===0?'high':'low'}">`,'hero-slide '+(i===heroIndex?'active':''),'aria-hidden="'+(i!==heroIndex)+'" tabindex="'+(i===heroIndex?'0':'-1')+'"')).join('')}<button class="carousel-arrow prev" data-action="hero-step" data-direction="-1" aria-label="Banner sebelumnya">${icon('left')}</button><button class="carousel-arrow next" data-action="hero-step" data-direction="1" aria-label="Banner berikutnya">${icon('arrow')}</button><div class="dots">${D.banners.map((_,i)=>`<button class="dot ${i===heroIndex?'active':''}" data-action="hero-dot" data-index="${i}" aria-label="Banner ${i+1}" aria-current="${i===heroIndex}"></button>`).join('')}</div></section></div></div>`;}
function promotionCover(p){
 const artwork=p.banner?image(p.banner,p.title,'promotion-banner'): `<div class="promotion-composite"><div class="promotion-copy"><span class="promotion-eyebrow">${t('Promosi')} · GOBI88</span><strong>${esc(p.title)}</strong><span class="promotion-more">Lihat detail ${icon('arrow')}</span></div>${image(p.coverImage,p.title,'promotion-poster')}</div>`;
 return link('/promotions/all/'+p.id,artwork,'promotion-cover','aria-label="'+esc(p.title)+'"');
}
function softTechSection(){return section('Soft Tech','arcade',`<div class="soft-tech-grid">${D.games.filter(g=>g.provider==='soft-tech').map(g=>link('/play/originals/'+g.id,`<span class="soft-tech-art">${image(g.image,g.title)}</span><strong>${esc(g.title)}</strong><span class="soft-tech-label">SOFT TECH ORIGINAL</span>`,'soft-tech-card')).join('')}</div>`,'','home-soft-tech');}
function home(){
 const slots=D.games.filter(g=>g.family==='slot');
 return hero()+announcement()+categoryNavigation()+softTechSection()+section('Hot Slots','hot',`<div class="game-grid">${slots.slice(0,8).map((g,i)=>card(g,i<3)).join('')}</div>`,'/slot/category/hot','home-hot-slots')+section('Promosi','promo',`<div class="promotion-list">${D.promotions.filter(p=>p.coverImage).map(promotionCover).join('')}</div>`,'/promotions/all','home-promotions');
}
const categoryNames={hot:'Hot',exclusive:'Exclusive',new:'New','buy-bonus':'Buy Bonus',table:'Table',megaways:'Megaways','spin-royal':'Spin Royal','level-up':'Level Up',lobby:'Lobby',top:'Top','game-shows':'Game Shows',roulette:'Roulette',baccarat:'Baccarat','sic-bo':'Sic Bo','dragon-tiger':'Dragon Tiger',blackjack:'Blackjack','ball-games':'Ball Games','idn-special':'IDN Special'};
function empty(title='Belum ada data',desc='Coba kategori atau filter lain.',cta=''){return `<div class="empty">${icon('search')}<h3>${t(title)}</h3><p>${desc}</p>${cta}</div>`;}
function searchForm(q=''){return `<form class="search-form" data-form="search"><input name="q" aria-label="${t('Cari permainan')}" placeholder="${t('Cari permainan')}" value="${esc(q)}" maxlength="100"><button class="btn" type="submit">${icon('search')}${t('Cari')}</button></form>`;}
function catalogue(family){
 const pth=path().split('/'),provider=pth[2]==='provider'?pth[3]:null,category=pth[2]==='category'?pth[3]:(family==='casino'?'lobby':'hot'),q=current().searchParams.get('q')||'',fav=current().searchParams.get('favorites')==='1';
 let games=D.games.filter(g=>g.family===family);
 const familyTitle=family==='slot'?'Slots':family==='casino'?'Casino':'Arcade';
 const providerOptions=family==='casino'?[...new Map(games.map(g=>[g.provider,{id:g.provider,name:g.providerName,path:'/casino/provider/'+g.provider}])).values()]:D.providers.filter(p=>p.family===family);
 if(provider)games=games.filter(g=>g.provider===provider);
 if(!provider&&category!=='hot'&&category!=='top'){
  if(category==='lobby')games=games.filter(g=>/lobby/i.test(g.title));
  else if(category==='exclusive'||category==='new'||category==='buy-bonus'||category==='megaways'||category==='level-up')games=games.filter(g=>g.tags.includes(category));
  else if(family==='casino')games=games.filter(g=>g.tags.includes(category)||category==='idn-special'&&g.provider==='idnlive');
  else if(category==='spin-royal')games=games.filter(g=>g.provider==='slotmania');
  else if(category==='table')games=games.filter(g=>/poker/i.test(g.title));
 }
 if(q)games=games.filter(g=>(g.title+' '+g.providerName).toLowerCase().includes(q.toLowerCase()));
 if(fav)games=games.filter(g=>S.favorites.includes(g.id));
 const cats=family==='casino'?['lobby','top','game-shows','roulette','baccarat','sic-bo','dragon-tiger','blackjack','ball-games','idn-special']:family==='slot'?['hot','exclusive','new','buy-bonus','table','megaways','spin-royal','level-up']:['hot','new'];
 const title=provider?(providerOptions.find(p=>p.id===provider)?.name||provider):(categoryNames[category]||familyTitle);
 return breadcrumbs()+`<div class="page-title"><h1>${familyTitle}</h1><span class="muted small-text">${games.length} permainan dalam katalog demo</span></div><div class="catalog-layout"><aside class="catalog-sidebar"><h3>Kategori</h3>${cats.map(c=>link('/'+family+'/category/'+c,categoryNames[c],'side-link '+(!provider&&category===c?'active':''))).join('')}<h3 style="margin-top:20px">Provider</h3>${providerOptions.map(p=>link(p.path,(p.image?image(p.image,p.name):'')+esc(p.name),'side-link '+(provider===p.id?'active':''))).join('')}</aside><div class="catalog-body"><div class="tabs" aria-label="Kategori game">${cats.map(c=>link('/'+family+'/category/'+c,categoryNames[c],'tab '+(!provider&&category===c?'active':''))).join('')}</div><section class="section"><div class="toolbar">${searchForm(q)}<select class="filter-select" aria-label="Filter provider" data-filter-provider data-family="${family}"><option value="">Semua provider</option>${providerOptions.map(p=>`<option value="${esc(p.id)}" ${provider===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select><button class="filter-favorites ${fav?'active':''}" data-action="filter-favorites">${icon('star')} ${t('Favorit')}</button></div><div class="catalog-heading"><h2>${esc(title)}</h2><span class="muted small-text">${games.length} hasil</span></div>${games.length?grid(games.slice(0,pageLimit)):empty('Tidak ada permainan','Katalog demo untuk filter ini belum tersedia. Pilih semua kategori untuk melihat game yang sudah disalin.',link('/'+family+'/category/hot','Lihat katalog','btn secondary'))}${games.length>pageLimit?'<div class="loading-more"><button class="btn secondary" data-action="more">Tampilkan lebih banyak</button></div>':''}</section></div></div>`;
}
function searchPage(){const q=current().searchParams.get('q')||'',fav=current().searchParams.get('favorites')==='1';const games=D.games.filter(g=>(!q||(g.title+' '+g.providerName).toLowerCase().includes(q.toLowerCase()))&&(!fav||S.favorites.includes(g.id)));return breadcrumbs()+`<div class="page-title"><h1>${t('Hasil pencarian')}</h1><button class="filter-favorites ${fav?'active':''}" data-action="filter-favorites">${icon('star')} ${t('Favorit')}</button></div><section class="section"><div class="toolbar">${searchForm(q)}</div><p class="load-result">${games.length} permainan ${q?'untuk “'+esc(q)+'”':''}</p>${games.length?grid(games.slice(0,pageLimit)):empty('Tidak ada permainan','Ubah kata kunci atau hapus filter favorit.')}${games.length>pageLimit?'<div class="loading-more"><button class="btn secondary" data-action="more">Tampilkan lebih banyak</button></div>':''}</section>`;}


function sportsPage(){const type=path().split('/')[2]||'',items=D.sports.filter(s=>!type||s.type===type);return breadcrumbs()+`<div class="page-title"><h1>Sports+</h1></div>${image(D.illustrations.sportsHero,'Sportsbook','wide-banner')}<div class="tabs">${[['','Semua'],['sport','Sports'],['esport','E-sports'],['virtual','Virtual']].map(([k,l])=>link('/sports'+(k?'/'+k:''),t(l),'tab '+(type===k?'active':''))).join('')}</div><div class="sports-grid">${items.map(s=>`<article class="sports-card">${image(s.image,s.title)}<div class="card-content"><h3>${esc(s.title)}</h3><button class="btn small" data-action="provider-preview" data-id="${s.id}">Main ${esc(s.title)}</button></div></article>`).join('')}</div>`;}
function exclusivePage(){return breadcrumbs()+`<div class="page-title"><h1>${t('Eksklusif')}</h1></div><section class="section"><div class="exclusive-grid" style="padding-top:16px">${D.exclusive.map(x=>link(x.path,image(x.image,x.title),'','aria-label="'+esc(x.title)+'"')).join('')}</div></section>`;}
function pokerPage(){const games=D.games.filter(g=>g.family==='poker');return breadcrumbs()+`<div class="page-title"><h1>Poker</h1></div>${image(D.illustrations.pokerHero,'Poker','wide-banner')}<div class="panel"><div class="form-actions"><span>Poker Username: <strong>PLAYGROUND_DEMO</strong></span><button class="btn secondary small" data-action="copy" data-value="PLAYGROUND_DEMO">${icon('copy')} Copy</button><button class="btn secondary" data-action="download-info">${icon('download')} Download Aplikasi</button><button class="btn" data-action="poker-preview">Main Sekarang</button><span class="demo-chip">DEMO</span></div></div>${section('Poker','poker',grid(games))}`;}
function fishingPage(){return breadcrumbs()+`<div class="page-title"><h1>Fishing</h1></div><div class="two-col"><section class="panel">${image(D.illustrations.fishing,'Fishing','feature-art')}</section><section class="panel"><h2>Fishing Arcade</h2><p class="muted">Jelajahi permainan fishing dari provider pilihan Anda.</p><p class="notice">Lobby Fishing siap untuk integrasi. Katalog provider belum terhubung dalam pratinjau ini.</p><button class="btn" data-action="fishing-preview">Pratinjau lobby</button><div class="form-actions">${link('/arcade/category/hot','Lihat Arcade','btn secondary')}</div></section></div>`;}
function lottoPage(){const sub=path().split('/')[2]||'popular',historyPage=sub==='results';return breadcrumbs()+`<div class="page-title"><h1>Lotto</h1><span class="demo-chip">DATA CONTOH</span></div><div class="tabs">${[['popular','Populer'],['lotto','Lotto'],['e-lottery','E-Lottery'],['lotteries','Semua'],['results','Histori']].map(([k,l])=>link('/lotto/'+k,t(l),'tab '+(sub===k?'active':''))).join('')}</div>${historyPage?`<div class="panel"><h2>Histori Hasil</h2><form data-form="lotto-history" class="form-actions"><input type="date" name="date" value="2026-11-03" aria-label="Tanggal hasil" style="max-width:200px"><button class="btn secondary">Tampilkan</button></form><div class="table-wrap"><table><thead><tr><th>Tanggal</th><th>Pasaran</th><th>Hasil contoh</th></tr></thead><tbody id="lotto-history-body">${[3,2,1].map((d,i)=>`<tr><td>${d} November 2026</td><td>Totomacau Pools</td><td>${['8179','4206','9351'][i]} <span class="demo-chip">DEMO</span></td></tr>`).join('')}</tbody></table></div></div>`:`<section class="result-card"><div><h2 style="margin:0;font-size:17px">Totomacau Pools</h2><p class="muted small-text">Hasil contoh · 3 November 2026</p></div><div class="result-digits" aria-label="Hasil contoh 8179"><span>8</span><span>1</span><span>7</span><span>9</span></div><div><div class="small-text muted">Countdown demo</div><strong class="countdown" data-countdown>00:59:59</strong></div>${link('/lotto/results/idn-lotto','Histori hasil','btn secondary')}</section>${section('E-Lottery','lotto',grid(D.games.filter(g=>g.family==='lotto')))}`}`;}
function promotionsPage(){const selected=path().split('/')[3],q=current().searchParams.get('category')||'all';if(selected){const p=D.promotions.find(x=>x.id===selected);if(!p)return notFound();return breadcrumbs()+`<div class="page-title"><h1>${esc(p.title)}</h1>${link('/promotions/all',t('Kembali'),'btn secondary small')}</div><div class="promo-detail"><div>${image(p.banner||p.image,p.title)}</div><section class="panel"><h2>${esc(p.title)}</h2><span class="status">${esc(p.period)}</span><p>${esc(p.summary)}</p><h3>Syarat & Ketentuan</h3><ul>${p.terms.map(x=>'<li>'+esc(x)+'</li>').join('')}</ul><p class="notice">Klaim pada halaman ini merupakan simulasi. Tidak ada bonus atau uang nyata yang diberikan.</p><button class="btn block" data-action="claim-promo" data-id="${p.id}" ${S.claimed.includes(p.id)?'disabled':''}>${S.claimed.includes(p.id)?'Sudah diklaim':'Coba klaim bonus demo'}</button></section></div>`;}
 const list=D.promotions.filter(p=>p.coverImage&&(q==='all'||p.category===q));return breadcrumbs()+`<div class="page-title"><h1>${t('Promosi')}</h1></div><div class="tabs">${[['all','Semua'],['slots','Slots'],['sports','Sports+']].map(([k,l])=>link('/promotions/all?category='+k,t(l),'tab '+(q===k?'active':''))).join('')}</div><section class="section"><div class="promotion-list" style="padding-top:16px">${list.map(promotionCover).join('')}</div></section>`;
}
function leaderboardPage(){return breadcrumbs()+`<div class="page-title"><h1>Leaderboard</h1><span class="demo-chip">SIMULASI</span></div><div class="tabs">${['distributed','weekly','monthly'].map((k,i)=>link('/leaderboard/'+k,['Dibagikan','Mingguan','Bulanan'][i],'tab '+(path().endsWith(k)?'active':''))).join('')}</div><section class="panel"><h2>${icon('trophy')} Peringkat Pemain Demo</h2><p class="muted">Contoh tampilan peringkat. Data live akan diisi oleh sistem Playground.</p><div class="table-wrap"><table><thead><tr><th>Peringkat</th><th>Pemain</th><th>Poin demo</th><th>Hadiah contoh</th></tr></thead><tbody>${['Naga***','Maha***','Bint***','Dewa***','Mega***','Raja***','Sena***','Arka***','Satu***','Bara***'].map((n,i)=>`<tr><td>${i<3?icon('trophy'):''} #${i+1}</td><td>${n}</td><td>${(150000-i*9371).toLocaleString('id-ID')}</td><td>${money(1000000-i*90000)}</td></tr>`).join('')}</tbody></table></div></section>`;}
function walletSummary(){return `<div class="panel wallet-summary"><div><div class="muted small-text">${t('Saldo demo')} <span class="demo-chip">SIMULASI</span></div><div class="wallet-number">${money(S.balance)}</div></div><div class="form-actions">${link('/deposit',icon('wallet')+'Deposit','btn green')}${link('/withdraw/bank-transfer',icon('bank')+'Withdraw','btn secondary')}</div></div>`;}
function field(label,name,value='',type='text',extra=''){return `<div class="field"><label for="f-${name}">${esc(label)}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;}
function txTable(rows){return rows.length?`<div class="table-wrap"><table><thead><tr><th>Tanggal</th><th>Transaksi</th><th>Metode</th><th>Nominal</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td>${date(x.createdAt)}</td><td>${x.type==='deposit'?'Deposit':'Withdraw'}</td><td>${esc(x.method)}</td><td>${money(x.amount)}</td><td><span class="status ${x.status}">${{pending:'Menunggu',completed:'Selesai',cancelled:'Dibatalkan'}[x.status]}</span></td><td><button class="text-button" data-action="receipt" data-id="${x.id}">Detail</button></td></tr>`).join('')}</tbody></table></div>`:empty('Belum ada data','Transaksi demo Anda akan muncul di sini.');}
function walletPage(withdraw=false){return walletSummary()+`<section class="panel"><h2>${withdraw?'Withdraw':'Deposit'}</h2><p class="notice">Mode simulasi: gunakan data contoh. Form ini tidak mengirim dana, membuat tagihan, atau menghubungi rekening/payment gateway.</p><form data-form="transaction" data-type="${withdraw?'withdraw':'deposit'}"><div class="form-grid"><div class="field"><label for="f-method">Metode ${withdraw?'withdraw':'deposit'}</label><select id="f-method" name="method">${(withdraw?['Bank Transfer','E-Wallet']:['QRIS','Virtual Account','Bank Transfer Manual','E-Wallet']).map(m=>'<option>'+m+'</option>').join('')}</select></div>${field('Nominal (IDR)','amount','','number','required min="10000" max="10000000" step="1" inputmode="numeric" placeholder="Minimal 10.000"')}</div><div class="amount-options">${[50000,100000,250000,500000,1000000].map(a=>`<button type="button" data-action="amount" data-amount="${a}">${money(a)}</button>`).join('')}</div>${withdraw?`<div class="form-grid"><div class="field"><label for="f-bank">Bank tujuan demo</label><select id="f-bank" name="bank"><option>BCA</option><option>Mandiri</option><option>BNI</option><option>BRI</option></select></div>${field('Nomor rekening demo','account','0000000000','text','required pattern="[0-9]{8,16}" inputmode="numeric"')}</div>`:''}<div class="field"><label for="f-note">Catatan (opsional)</label><input id="f-note" name="note" maxlength="120" placeholder="Catatan transaksi demo"></div><button class="btn ${withdraw?'':'green'}" type="submit">${withdraw?'Ajukan withdraw demo':'Buat deposit demo'}</button><p class="form-error" role="alert"></p></form></section><section class="panel"><h2>Transaksi Terakhir</h2>${txTable(S.transactions.filter(x=>x.type===(withdraw?'withdraw':'deposit')).slice(0,5))}</section>`;}
function profilePage(){return walletSummary()+`<section class="panel"><h2>${t('Informasi akun')}</h2><form data-form="profile"><p class="auth-note">Gunakan data contoh untuk menguji profil. Perubahan tersimpan di browser ini.</p><div class="form-grid">${field('Username demo','name',S.user.name,'text','required minlength="3" maxlength="24" pattern="[a-zA-Z0-9_]+"') }${field('Email demo','email',S.user.email,'email','required maxlength="100"')}</div><div class="form-actions"><button class="btn" type="submit">${t('Simpan')}</button><button type="button" class="btn secondary" data-action="logout">${t('Keluar')}</button></div><p class="form-error" role="alert"></p></form></section><section class="panel"><h2>Favorit Saya</h2>${S.favorites.length?grid(D.games.filter(g=>S.favorites.includes(g.id)).slice(0,12)):empty('Belum ada data','Tekan bintang pada kartu game untuk menyimpan favorit.',link('/slot/category/hot','Jelajahi Slots','btn secondary'))}</section>`;}
function bonusesPage(){return walletSummary()+`<section class="panel"><h2>Bonus & Free Spins</h2><p class="notice">Bonus ini hanya menambah saldo simulasi di browser Anda.</p><div class="bonus-grid">${[['welcome','Bonus Selamat Datang',25000],['daily','Bonus Harian',10000]].map(([k,l,a])=>`<article class="bonus-card"><h3>${icon('gift')} ${l}</h3><div class="bonus-value">${money(a)}</div><p>Satu kali klaim per data demo.</p><button class="btn" data-action="claim-bonus" data-id="${k}" data-amount="${a}" ${S.claimed.includes(k)?'disabled':''}>${S.claimed.includes(k)?'Sudah diklaim':'Klaim demo'}</button></article>`).join('')}</div><h3 style="margin-top:25px">Free Spins</h3><p class="muted">Tidak ada freespin yang tersedia.</p></section>`;}
function referralPage(){const referral=location.origin+'/referral?code=PLAYGROUND-DEMO';return `<div class="stat-grid"><div class="stat"><small>Total Referral</small><strong>0</strong><span class="small-text muted">Akun demo</span></div><div class="stat"><small>Komisi Demo</small><strong>Rp 0</strong><span class="small-text muted">Belum ada komisi</span></div><div class="stat"><small>Status</small><strong>Aktif</strong><span class="small-text muted">Simulasi</span></div></div><section class="panel"><h2>Undang Teman</h2><p class="muted">Salin tautan contoh untuk melihat alur referral.</p><div class="copy-field"><input readonly value="${esc(referral)}" aria-label="Tautan referral demo"><button class="btn" data-action="copy" data-value="${esc(referral)}">${icon('copy')} Salin</button></div><div class="tabs">${link('/user/referral/history','Histori Referral','tab active')}</div>${empty('Belum ada data','Referral dan komisi akan berasal dari backend Playground setelah integrasi.')}</section>`;}
function messagesPage(){return `<section class="panel"><h2>Inbox <span class="demo-chip">${S.messages.filter(m=>!m.read).length} UNREAD</span></h2><button class="text-button" data-action="read-all">Tandai semua dibaca</button>${S.messages.map(m=>`<button class="message ${m.read?'':'unread'}" data-action="message" data-id="${m.id}"><div><h3>${esc(m.title)}</h3><p>${esc(m.text.slice(0,90))}…</p></div>${icon('arrow')}</button>`).join('')}</section>`;}
function activityPage(){const kind=current().searchParams.get('type')||'all',status=current().searchParams.get('status')||'all';const rows=S.transactions.filter(x=>(kind==='all'||x.type===kind)&&(status==='all'||x.status===status));return `<section class="panel"><h2>${t('Aktivitas')}</h2><form class="form-actions" data-form="activity-filter"><select name="type" aria-label="Jenis transaksi" style="max-width:190px">${[['all','Semua transaksi'],['deposit','Deposit'],['withdraw','Withdraw']].map(([k,l])=>`<option value="${k}" ${kind===k?'selected':''}>${l}</option>`).join('')}</select><select name="status" aria-label="Status transaksi" style="max-width:180px">${[['all','Semua status'],['pending','Menunggu'],['completed','Selesai'],['cancelled','Dibatalkan']].map(([k,l])=>`<option value="${k}" ${status===k?'selected':''}>${l}</option>`).join('')}</select><button class="btn secondary">Filter</button></form>${txTable(rows)}</section><section class="panel"><h2>Aktivitas Akun Demo</h2>${S.activity.length?`<div class="table-wrap"><table><thead><tr><th>Waktu</th><th>Aktivitas</th></tr></thead><tbody>${S.activity.slice(0,30).map(a=>`<tr><td>${date(a.time)}</td><td>${esc(a.text)}</td></tr>`).join('')}</tbody></table></div>`:empty('Belum ada data','Aktivitas demo akan ditampilkan setelah Anda mencoba workflow.')}</section>`;}
function historyPage(){const rows=S.activity.filter(a=>a.text.startsWith('Preview game:'));return `<section class="panel"><h2>${t('Riwayat Bermain')}</h2><p class="notice">Riwayat ini mencatat pratinjau game. Tidak ada taruhan, kemenangan, atau hasil provider nyata.</p>${rows.length?`<div class="table-wrap"><table><thead><tr><th>Waktu</th><th>Game</th><th>Status</th></tr></thead><tbody>${rows.map(a=>`<tr><td>${date(a.time)}</td><td>${esc(a.text.replace('Preview game: ',''))}</td><td><span class="status">Preview</span></td></tr>`).join('')}</tbody></table></div>`:empty('Belum ada data','Buka pratinjau salah satu game untuk mencoba alur histori.',link('/slot/category/hot','Jelajahi game','btn'))}</section>`;}
function memberPage(){if(!S.signedIn)return breadcrumbs()+`<div class="panel">${empty('Akun demo belum masuk','Masuk menggunakan identitas demo untuk mencoba halaman member.','<button class="btn" data-action="auth" data-mode="login">Masuk akun demo</button>')}</div>`;let content=path()==='/deposit'?walletPage():path().startsWith('/withdraw')?walletPage(true):path().includes('/bonuses')?bonusesPage():path().includes('/referral')?referralPage():path().includes('/messages')?messagesPage():path().includes('/activity')?activityPage():path().includes('/history')?historyPage():profilePage();return breadcrumbs()+`<div class="page-title"><h1>${t('Akun Saya')}</h1><span class="demo-chip">PLAYGROUND DEMO</span></div><div class="account-layout"><aside class="account-sidebar"><div class="account-avatar">${icon('user')}</div><h3>${esc(S.user.name)}</h3><span class="small-text muted">Member demo</span><nav class="account-links" aria-label="Navigasi akun" tabindex="0">${accountLinks()}</nav></aside><div class="account-content">${content}</div></div>`;}
const info={
 '/about-us':['Tentang Kami','Playground Agent Frontend adalah template antarmuka yang memadukan katalog permainan, promosi, dan area member dalam satu website responsive.','Pratinjau ini memakai struktur dan aset visual referensi GOBI88. Semua aktivitas akun dan wallet merupakan simulasi lokal, terpisah dari website referensi.'],
 '/legal/responsible-gaming':['Responsible Gaming','Halaman ini adalah contoh struktur informasi untuk template Playground. Pratinjau tidak menyediakan perjudian atau transaksi uang nyata.','Pada layanan terintegrasi, agen perlu menyediakan pengaturan batas, waktu bermain, penghentian akses dan jalur bantuan sesuai kebijakan operasionalnya.'],
 '/legal/terms-and-conditions':['Syarat & Ketentuan','Ini adalah pratinjau frontend, bukan layanan permainan atau pembayaran aktif. Akun, saldo, transaksi dan hadiah yang ditampilkan merupakan data demo.','Konten ketentuan operasional final harus diisi oleh pengelola agen sebelum layanan backend diaktifkan. Tombol dan validasi pada demo bertujuan menguji pengalaman pengguna.'],
 '/legal/privacy-policy':['Kebijakan Privasi','Pratinjau menyimpan data demo seperti favorit, saldo simulasi dan histori pada penyimpanan browser perangkat ini. Form demo tidak mengirim data tersebut ke backend.','Gunakan identitas contoh. Anda dapat menghapus data simulasi melalui tombol Reset data demo di footer. Tidak ada tracker atau widget chat pihak ketiga yang disertakan.']
};
function infoPage(){const row=info[path()];return breadcrumbs()+`<div class="page-title"><h1>${row[0]}</h1></div><section class="panel info-content">${row.slice(1).map(p=>'<p>'+p+'</p>').join('')}<p class="notice">Dokumen contoh template. Konten final mengikuti konfigurasi dan kebijakan agen Playground.</p></section>`;}
function contactPage(complaint=false){return breadcrumbs()+`<div class="page-title"><h1>${complaint?'Pengaduan Konsumen':t('Kontak')}</h1></div>${complaint?'':`<div class="contact-grid"><div class="contact-card">${icon('chat')}<h3>Live Chat</h3><p>Coba percakapan bantuan demo.</p><button class="btn" data-action="chat">Buka Chat</button></div><div class="contact-card">${icon('mail')}<h3>Inbox Member</h3><p>Temukan pesan dan pengumuman.</p>${link('/user/messages','Buka Inbox','btn secondary')}</div><div class="contact-card">${icon('user')}<h3>Pengaduan</h3><p>Simulasikan tiket bantuan.</p>${link('/complaint','Buat Tiket','btn secondary')}</div></div>`}<section class="panel" style="margin-top:16px"><h2>${complaint?'Form Pengaduan':'Hubungi Kami'}</h2><p class="auth-note">Pesan disimpan sebagai tiket demo lokal, tidak dikirim kepada GOBI88 atau pihak lain.</p><form data-form="support"><div class="form-grid">${field('Nama demo','name',S.user.name,'text','required maxlength="50"')}${field('Email demo','email',S.user.email,'email','required maxlength="100"')}</div>${field('Subjek','subject','','text','required maxlength="120"')}<div class="field"><label for="f-message">Pesan</label><textarea id="f-message" name="message" required minlength="10" maxlength="2000" placeholder="Tuliskan contoh pertanyaan atau kendala"></textarea></div><button class="btn" type="submit">Simpan tiket demo</button><p class="form-error" role="alert"></p></form></section>`;}
function originalGamePage(g){return breadcrumbs()+`<div class="page-title"><h1>${esc(g.title)}</h1>${link('/','Kembali','btn secondary small')}</div><section class="panel original-detail">${image(g.hero,g.title,'original-hero',true)}<div class="original-copy"><span class="soft-tech-label">SOFT TECH ORIGINAL</span><h2>${esc(g.title)}</h2><p>${esc(g.description)}</p><p class="muted">Game dibuka di website Soft Tech dalam tab baru. Akun dan wallet 64COR belum tersinkron ke game.</p><a class="btn" href="${esc(g.launchUrl)}" target="_blank" rel="noopener noreferrer">${icon('play')} Buka game</a><button class="btn secondary" data-action="favorite" data-id="${g.id}" aria-pressed="${S.favorites.includes(g.id)}">${icon('star')} ${S.favorites.includes(g.id)?'Hapus favorit':'Simpan favorit'}</button></div></section>`;}
function gamePage(){const gid=path().split('/').pop(),g=D.games.find(x=>x.id===gid);if(!g)return notFound();if(g.provider==='soft-tech')return originalGamePage(g);return breadcrumbs()+`<div class="page-title"><h1>${esc(g.title)}</h1>${link('/'+(g.family==='slot'?'slot/category/hot':g.family==='casino'?'casino/category/lobby':g.family==='arcade'?'arcade/category/hot':g.family),'Kembali','btn secondary small')}</div><section class="panel"><div class="preview-game">${image(g.image,g.title)}<h3>${esc(g.title)}</h3><p>${esc(g.providerName)} · <span class="demo-chip">PREVIEW UI</span></p><p>Peluncuran provider belum terhubung. Buka sesi pratinjau untuk mencoba alur dan pencatatan histori.</p><button class="btn" data-action="launch-demo" data-id="${g.id}">${icon('play')} Buka pratinjau demo</button></div></section>${section('Pilihan lainnya',g.family==='slot'?'slots':g.family,grid(D.games.filter(x=>x.family===g.family&&x.id!==g.id).slice(0,6)))}`;}
function notFound(){return '<div class="panel">'+empty('Halaman tidak ditemukan','Gunakan navigasi untuk melanjutkan.',link('/','Kembali ke beranda','btn'))+'</div>';}
function content(){const p=path();if(p==='/'||p==='/en')return home();if(p.startsWith('/play/'))return gamePage();if(p.startsWith('/slot'))return catalogue('slot');if(p.startsWith('/casino'))return catalogue('casino');if(p.startsWith('/arcade'))return catalogue('arcade');if(p==='/exclusive')return exclusivePage();if(p.startsWith('/sports'))return sportsPage();if(p==='/poker')return pokerPage();if(p.startsWith('/lotto'))return lottoPage();if(p==='/fishing')return fishingPage();if(p.startsWith('/promotions'))return promotionsPage();if(p.startsWith('/leaderboard'))return leaderboardPage();if(p==='/search')return searchPage();if(p.startsWith('/user')||p==='/deposit'||p.startsWith('/withdraw'))return memberPage();if(p==='/referral')return breadcrumbs()+referralPage();if(info[p])return infoPage();if(p==='/contact'||p==='/complaint')return contactPage(p==='/complaint');if(p==='/sns')return breadcrumbs()+`<div class="page-title"><h1>Stream n'Spin</h1></div>${image(D.illustrations.sns,"Stream n'Spin",'wide-banner')}<div class="panel"><h2>Live Stream & Games</h2><p class="muted">Pratinjau tampilan streaming. Flux video live belum terhubung.</p>${link('/slot/category/hot','Jelajahi Slots','btn')}</div>`;if(['/login','/register','/forgot-password'].includes(p))return breadcrumbs()+`<div class="panel"><h1>Akun Demo</h1><button class="btn" data-action="auth" data-mode="${p.slice(1)==='forgot-password'?'forgot':p.slice(1)}">Buka form</button></div>`;return notFound();}
function renderBottomNav(){
 const items=[['home','Beranda','/'],['search','Cari','/search'],['wallet','Deposit','/deposit'],['gift','Promo','/promotions/all'],['user','Akun','/user']];
 const p=path(),index=p==='/'||p==='/en'?0:p==='/deposit'?2:p.startsWith('/promotions')?3:/^\/(user|withdraw|referral|login|register|forgot-password)(\/|$)/.test(p)?4:/^\/(search|slot|casino|arcade|play|poker|lotto|fishing|sports|exclusive)(\/|$)/.test(p)?1:-1;
 const root=document.querySelector('#bottom-nav-root');
 if(!root.firstElementChild)root.innerHTML=`<nav class="mobile-bottom floating-nav" aria-label="Navigasi utama"><span class="nav-indicator" aria-hidden="true"><span class="nav-glass"></span></span>${items.map(([i,label,url])=>link(url,pixelIcon(i)+`<span data-nav-label>${t(label)}</span>`,'dock-link')).join('')}</nav>`;
 const nav=root.firstElementChild,previous=nav.dataset.activeIndex;
 nav.dataset.activeIndex=String(index);nav.style.setProperty('--active-index',String(Math.max(0,index)));
 nav.querySelectorAll('.dock-link').forEach((el,i)=>{el.classList.toggle('active',i===index);el.querySelector('[data-nav-label]').textContent=t(items[i][1]);if(i===index)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});
 const lens=nav.querySelector('.nav-glass');
 if(previous!==undefined&&previous!==String(index)&&index>=0&&!matchMedia('(prefers-reduced-motion: reduce)').matches&&lens.animate){lens.getAnimations().forEach(a=>a.cancel());lens.animate([{transform:'scaleX(1) scaleY(1)'},{transform:'scaleX(1.16) scaleY(.90)',offset:.35},{transform:'scaleX(.97) scaleY(1.03)',offset:.8},{transform:'scaleX(1) scaleY(1)'}],{duration:560,easing:'cubic-bezier(.2,.7,.2,1)'});}
}
function render(){document.documentElement.lang=S.locale;const isHome=path()==='/';app.innerHTML=header()+`<main id="main" class="container ${isHome?'home-page':''}">${isHome?'':announcement()+categoryNavigation()}${content()}</main>`+footer();renderBottomNav();document.title=(app.querySelector('h1')?.textContent||'Selamat Datang')+' · 64COR';}


function modal(title,html,wide=false){closeModal(false);returnFocus=document.activeElement;overlays.innerHTML=`<div class="overlay" data-overlay><section class="dialog ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}" tabindex="-1"><header class="dialog-head"><h2>${esc(title)}</h2><button class="icon-button" data-action="close" aria-label="${t('Tutup')}">${icon('close')}</button></header><div class="dialog-body">${html}</div></section></div>`;document.body.classList.add('modal-open');overlays.querySelector('input,button,select,textarea')?.focus();}
function closeModal(restore=true){overlays.innerHTML='';document.body.classList.remove('modal-open');if(restore&&returnFocus?.isConnected)returnFocus.focus();}
function drawer(){closeModal(false);returnFocus=document.activeElement;overlays.innerHTML=`<div class="overlay drawer-overlay" data-overlay><aside class="drawer" role="dialog" aria-modal="true" aria-label="Menu utama" tabindex="-1"><div class="drawer-head">${brandLogo()}<button class="icon-button" data-action="close" aria-label="Tutup menu">${icon('close')}</button></div><p class="demo-notice">Playground frontend preview · Demo</p><div class="drawer-categories">${link('/search',pixelIcon('search')+'<span>Cari</span>','nav-item')}${navMarkup()}</div><nav class="account-links">${accountLinks()}<button class="side-link" data-action="freespins">${icon('gift')} Free Spins</button><button class="side-link" data-action="${S.signedIn?'logout':'auth'}" data-mode="login">${icon('logout')} ${t(S.signedIn?'Keluar':'Masuk')}</button></nav>${link('/deposit',icon('wallet')+' Deposit','btn green block')}<div class="language-picker"><span>Pilih Bahasa:</span><button data-action="locale" data-locale="id" aria-label="Bahasa Indonesia">${image(D.flags.id,'Indonesia')}</button><button data-action="locale" data-locale="en" aria-label="English">${image(D.flags.en,'English')}</button></div></aside></div>`;document.body.classList.add('modal-open');overlays.querySelector('button').focus();}
function auth(mode='login'){
 const title=mode==='register'?'Daftar Akun Demo':mode==='forgot'?'Lupa Password — Demo':'Masuk Akun Demo';
 modal(title,`<p class="auth-note">Pratinjau Playground. Gunakan data contoh; tidak terhubung ke akun GOBI88. Password tidak disimpan atau dikirim.</p><form data-form="auth" data-mode="${mode}">${mode!=='forgot'?field('Username demo','username',mode==='login'?'playground_demo':'','text','required minlength="3" maxlength="24" pattern="[a-zA-Z0-9_]+" autocomplete="off"'):''}${mode!=='login'?field('Email demo','email',mode==='forgot'?'demo@example.test':'','email','required maxlength="100" autocomplete="off"'):''}${mode!=='forgot'?field(mode==='login'?'Password demo: demo1234':'Password demo','password',mode==='login'?'demo1234':'','password','required minlength="8" maxlength="64" autocomplete="off"'):''}${mode==='register'?field('Konfirmasi password demo','confirm','','password','required minlength="8" maxlength="64" autocomplete="off"'):''}<button class="btn block" type="submit">${mode==='register'?'Buat akun demo':mode==='forgot'?'Simulasikan reset':t('Masuk')}</button><p class="form-error" role="alert"></p></form><div class="auth-switch">${mode==='login'?'<button class="text-button" data-action="auth" data-mode="register">Daftar demo</button> · <button class="text-button" data-action="auth" data-mode="forgot">Lupa password?</button>':'<button class="text-button" data-action="auth" data-mode="login">Kembali ke login</button>'}</div>`);
}
function receipt(txid){const tx=S.transactions.find(x=>x.id===txid);if(!tx)return;modal('Detail Transaksi Demo',`<div class="notice">SIMULASI — Tidak ada tagihan, kode pembayaran, atau transfer uang nyata.</div><div class="receipt"><div class="receipt-row"><span>Referensi</span><strong>${esc(tx.id.slice(0,8).toUpperCase())}</strong></div><div class="receipt-row"><span>Jenis</span><strong>${tx.type==='deposit'?'Deposit':'Withdraw'}</strong></div><div class="receipt-row"><span>Metode</span><strong>${esc(tx.method)}</strong></div><div class="receipt-row"><span>Nominal</span><strong>${money(tx.amount)}</strong></div><div class="receipt-row"><span>Status</span><span class="status ${tx.status}">${{pending:'Menunggu',completed:'Selesai',cancelled:'Dibatalkan'}[tx.status]}</span></div></div>${tx.status==='pending'?`<p class="muted small-text">${tx.type==='withdraw'?'Saldo demo telah dicadangkan. Pembatalan mengembalikannya satu kali.':'Saldo bertambah setelah simulasi pembayaran diselesaikan.'}</p><div class="form-actions"><button class="btn green" data-action="settle" data-id="${tx.id}" data-status="completed">${tx.method==='Bank Transfer Manual'?'Simulasikan approval':'Simulasikan selesai'}</button><button class="btn secondary" data-action="settle" data-id="${tx.id}" data-status="cancelled">Batalkan demo</button></div>`:`<div class="form-actions">${link('/user/activity','Lihat aktivitas','btn')}<button class="btn secondary" data-action="close">Tutup</button></div>`}`);}
function openChat(){modal('Live Chat Demo',`<div class="chat-messages">${chatMessages.map(m=>`<div class="chat-bubble ${m.self?'self':''}">${esc(m.text)}</div>`).join('')}</div><form class="chat-form" data-form="chat"><input name="message" placeholder="Tulis pesan demo…" aria-label="Pesan demo" required maxlength="500" autocomplete="off"><button class="btn" aria-label="Kirim pesan demo">${icon('arrow')}</button></form><p class="small-text muted">Balasan otomatis lokal • Tidak dikirim ke customer service.</p>`);const box=overlays.querySelector('.chat-messages');box.scrollTop=box.scrollHeight;}
async function showHero(index){
 const next=(index+D.banners.length)%D.banners.length,request=++heroRequest;
 const slide=document.querySelectorAll('.hero-slide')[next],img=slide?.querySelector('img');
 if(!slide||!img)return;
 // Keep the current banner visible until the requested image is decoded.
 // Hidden lazy images otherwise produce a blank carousel on a slow connection.
 if(typeof img.decode==='function'){try{await img.decode();}catch{return;}}
 if(request!==heroRequest||!slide.isConnected)return;
 heroIndex=next;
 document.querySelectorAll('.hero-slide').forEach((e,i)=>{e.classList.toggle('active',i===heroIndex);e.setAttribute('aria-hidden',String(i!==heroIndex));e.tabIndex=i===heroIndex?0:-1;});
 document.querySelectorAll('.carousel .dot').forEach((e,i)=>{e.classList.toggle('active',i===heroIndex);e.setAttribute('aria-current',String(i===heroIndex));});
}
async function action(button){
 const a=button.dataset.action;
 if(a==='close')return closeModal();
 if(a==='drawer')return drawer();
 if(a==='auth')return auth(button.dataset.mode);
 if(a==='chat')return openChat();
 if(a==='hero-step')return showHero(heroIndex+Number(button.dataset.direction));
 if(a==='hero-dot')return showHero(Number(button.dataset.index));
 if(a==='special'){specialIndex=Number(button.dataset.index);return rerender();}
 if(a==='rail'){button.closest('.provider-section').querySelector('.rail').scrollBy({left:Number(button.dataset.direction)*300,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});return;}
 if(a==='favorite'){S=toggleFavorite(S,button.dataset.id);save();rerender();return;}
 if(a==='filter-favorites'){const u=current();u.searchParams.get('favorites')?u.searchParams.delete('favorites'):u.searchParams.set('favorites','1');return go(u.pathname+u.search);}
 if(a==='more'){pageLimit+=30;return rerender();}
 if(a==='amount'){const f=button.closest('form');f.elements.amount.value=button.dataset.amount;f.elements.amount.focus();return;}
 if(a==='receipt')return receipt(button.dataset.id);
 if(a==='settle'){const before=S.transactions.find(x=>x.id===button.dataset.id);S=settleTransaction(S,button.dataset.id,button.dataset.status);if(before?.status==='pending')log('Transaksi demo '+button.dataset.status+': '+before.id.slice(0,8));save();rerender();return receipt(button.dataset.id);}
 if(a==='claim-bonus'||a==='claim-promo'){try{S=claimBonus(S,button.dataset.id,a==='claim-bonus'?Number(button.dataset.amount):5000);log('Klaim bonus demo: '+button.dataset.id);save();rerender();toast('Bonus ditambahkan ke saldo demo.');}catch(e){toast(e.message);}return;}
 if(a==='message'){const m=S.messages.find(x=>x.id===button.dataset.id);m.read=true;save();rerender();return modal(m.title,`<p>${esc(m.text)}</p>`);}
 if(a==='read-all'){S.messages.forEach(m=>m.read=true);save();return rerender();}
 if(a==='logout'){log('Keluar dari akun demo');S.signedIn=false;save();go('/');return toast('Anda keluar dari sesi demo.');}
 if(a==='locale'){S.locale=button.dataset.locale;save();closeModal();return rerender();}
 if(a==='freespins')return modal('Free Spins','<p>Tidak ada freespin yang tersedia.</p><p class="small-text muted">Bonus akan disinkronkan setelah integrasi backend Playground.</p>');
 if(a==='copy'){try{await navigator.clipboard.writeText(button.dataset.value);toast('Berhasil disalin.');}catch{modal('Salin teks',`<input readonly value="${esc(button.dataset.value)}" aria-label="Teks untuk disalin"><p class="small-text muted">Pilih teks dan salin secara manual.</p>`);}return;}
 if(a==='provider-preview'){const s=D.sports.find(x=>x.id===button.dataset.id);return modal(s.title,`<div class="preview-game">${image(s.image,s.title)}<h3>${esc(s.title)}</h3><p>Lobby provider dalam mode pratinjau. Integrasi sesi provider dilakukan pada tahap backend.</p></div>`);}
 if(a==='poker-preview'){return go('/play/poker/'+D.games.find(g=>g.family==='poker').id);}
 if(a==='fishing-preview')return modal('Fishing Lobby',`<div class="preview-game">${image(D.illustrations.fishing,'Fishing')}<h3>Fishing</h3><p>Kontainer lobby siap untuk katalog dan sesi provider Playground.</p>${link('/arcade/category/hot','Lihat Arcade','btn')}</div>`);
 if(a==='download-info')return modal('Download Aplikasi','<p>Aplikasi agen belum tersedia pada pratinjau ini.</p><p class="muted">Tombol download siap dikonfigurasi dengan file aplikasi milik agen ketika tersedia.</p>');
 if(a==='launch-demo'){const g=D.games.find(x=>x.id===button.dataset.id);log('Preview game: '+g.title);return modal(g.title,`<div class="preview-game">${image(g.image,g.title)}<h3>Sesi preview siap</h3><p>Alur pembukaan game berhasil dan sudah dicatat di histori demo.</p><span class="demo-chip">TANPA TARUHAN · TANPA UANG NYATA</span><div class="form-actions" style="justify-content:center">${link('/user/history','Lihat histori','btn secondary')}<button class="btn" data-action="close">Kembali ke game</button></div></div>`,true);}
 if(a==='reset-prompt')return modal('Reset Data Demo','<p>Hapus perubahan lokal dan kembalikan akun, saldo, favorit serta histori ke kondisi awal demo?</p><div class="form-actions"><button class="btn" data-action="reset">Reset demo</button><button class="btn secondary" data-action="close">Batal</button></div>');
 if(a==='reset'){S=initialState();save();go('/');return toast('Data demo dikembalikan ke kondisi awal.');}
}
document.addEventListener('click',e=>{
 const b=e.target.closest('[data-action]');if(b){e.preventDefault();action(b).catch(error=>toast(error.message||'Aksi belum berhasil.'));return;}
 const a=e.target.closest('a[data-route]');if(a&&!e.metaKey&&!e.ctrlKey&&!e.shiftKey&&e.button===0){e.preventDefault();if(swipeIgnore){swipeIgnore=false;return;}go(a.getAttribute('href'));return;}
 if(e.target.hasAttribute('data-overlay'))closeModal();
});
document.addEventListener('change',e=>{if(e.target.matches('[data-filter-provider]')){const family=e.target.dataset.family;go(e.target.value?'/'+family+'/provider/'+encodeURIComponent(e.target.value):'/'+family+'/category/'+(family==='casino'?'lobby':'hot'));}});
document.addEventListener('submit',e=>{
 const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();const f=new FormData(form),formType=form.dataset.form;const err=form.querySelector('.form-error');if(err)err.textContent='';
 try{
  if(formType==='search'){const u=current();u.searchParams.set('q',String(f.get('q')).trim());if(path()==='/')u.pathname='/search';go(u.pathname+u.search);}
  if(formType==='auth'){const mode=form.dataset.mode;if(mode==='forgot'){modal('Reset Demo Disimulasikan','<p>Alur permintaan reset berhasil disimulasikan.</p><p class="muted">Tidak ada email atau password akun nyata yang diubah. Untuk masuk kembali, gunakan password demo <strong>demo1234</strong>.</p><button class="btn" data-action="auth" data-mode="login">Kembali ke login</button>');return;}if(mode==='login'&&f.get('password')!=='demo1234')throw new Error('Gunakan password demo: demo1234.');if(mode==='register'&&f.get('password')!==f.get('confirm'))throw new Error('Konfirmasi password tidak sama.');if(mode==='register'){S=initialState();S.user.email=String(f.get('email'));}S.user.name=String(f.get('username'));S.signedIn=true;log(mode==='login'?'Masuk akun demo':'Registrasi akun demo');save();go('/user');toast(mode==='login'?'Berhasil masuk ke akun demo.':'Akun demo dibuat. Password login demo: demo1234.');}
  if(formType==='profile'){S.user={...S.user,name:String(f.get('name')),email:String(f.get('email'))};log('Profil demo diperbarui');save();rerender();toast('Profil demo tersimpan.');}
  if(formType==='transaction'){const txid=id();S=createTransaction(S,{type:form.dataset.type,amount:f.get('amount'),method:String(f.get('method')),id:txid,now:new Date().toISOString()});log('Pengajuan '+form.dataset.type+' demo: '+txid.slice(0,8));save();rerender();receipt(txid);}
  if(formType==='activity-filter')go('/user/activity?type='+encodeURIComponent(f.get('type'))+'&status='+encodeURIComponent(f.get('status')));
  if(formType==='support'){const ticket='DEMO-'+id().slice(0,8).toUpperCase();S.messages.unshift({id:ticket,title:ticket+' · '+String(f.get('subject')),text:'Tiket demo lokal tersimpan: '+String(f.get('message')),read:false});log('Tiket bantuan demo '+ticket);save();form.reset();modal('Tiket Demo Tersimpan',`<p>Nomor tiket: <strong>${ticket}</strong></p><p class="muted">Pesan hanya tersimpan di browser ini. Tidak dikirim ke pihak lain.</p>${link('/user/messages','Lihat Inbox','btn')}`);}
  if(formType==='chat'){const text=String(f.get('message')).trim();if(!text)return;chatMessages.push({self:true,text});const lower=text.toLowerCase();chatMessages.push({self:false,text:lower.includes('deposit')?'Buka menu Deposit, pilih metode dan nominal, lalu coba tombol Simulasikan selesai pada detail transaksi.':lower.includes('withdraw')?'Buka Withdraw. Saldo demo dicadangkan saat pengajuan; jika dibatalkan, saldo dikembalikan satu kali.':lower.includes('bonus')?'Buka Bonus di menu akun. Setiap bonus demo hanya dapat diklaim satu kali.':'Terima kasih. Ini adalah balasan demo lokal. Anda dapat mencoba pencarian game, favorit, promosi, atau workflow member dari menu.'});openChat();}
  if(formType==='lotto-history'){document.querySelector('#lotto-history-body').innerHTML=`<tr><td>${esc(f.get('date'))}</td><td>Totomacau Pools</td><td>8179 <span class="demo-chip">DATA CONTOH</span></td></tr>`;toast('Filter tanggal contoh diterapkan.');}
 }catch(error){if(err)err.textContent=error.message;else toast(error.message);}
});
document.addEventListener('keydown',e=>{
 if(e.key==='Escape'){closeModal();return;}
 if(e.key==='Tab'&&overlays.firstElementChild){const focusable=[...overlays.querySelectorAll('button:not(:disabled),a,input,select,textarea,[tabindex="0"]')].filter(x=>x.offsetParent!==null);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}
});
document.addEventListener('error',e=>{if(e.target.tagName==='IMG'&&!e.target.dataset.fallback){e.target.dataset.fallback='true';e.target.src=D.games[0].image;}},true);
let swipeStart=null,swipeIgnore=false;
document.addEventListener('pointerdown',e=>{if(e.target.closest('.carousel'))swipeStart={x:e.clientX,y:e.clientY};});
document.addEventListener('pointerup',e=>{if(!swipeStart)return;const dx=e.clientX-swipeStart.x,dy=e.clientY-swipeStart.y;swipeStart=null;if(Math.abs(dx)>45&&Math.abs(dx)>Math.abs(dy)){showHero(heroIndex+(dx<0?1:-1));swipeIgnore=true;setTimeout(()=>swipeIgnore=false,200);}});
window.addEventListener('popstate',()=>{closeModal();pageLimit=30;render();});
setInterval(()=>{if(!document.hidden&&!overlays.firstElementChild&&!matchMedia('(prefers-reduced-motion: reduce)').matches&&document.querySelector('.carousel')&&!document.querySelector('.carousel:hover')&&!document.querySelector('.carousel:focus-within'))showHero(heroIndex+1);},6000);
setInterval(()=>{document.querySelectorAll('[data-countdown]').forEach(el=>{const seconds=3600-Math.floor(Date.now()/1000)%3600;el.textContent='00:'+String(Math.floor(seconds/60)%60).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');});},1000);
if(path()==='/en'){S.locale='en';save();history.replaceState({},'','/');}
render();
